 return {url:location.href,title:document.title,h1:document.querySelector('h1')?.innerText,key_text:idx>=0?lines[idx]:lines.find(s=>/career|opening|position/i.test(s))||'',values:idx>=0?lines.slice(idx,idx+15):[],answer:idx>=0?lines.slice(idx,idx+15).join('\n'):text};
