await page.evaluate(async () => {
 const link = [...document.querySelectorAll('a')].find(a => /open positions|view.*open|see.*open|current openings|explore.*jobs/i.test(a.innerText));
 if (link && link.href && !link.href.includes('#')) { location.href = link.href; }
 else { const marketing=[...document.querySelectorAll('button,select')].find(e=>/marketing/i.test(e.textContent)); if(marketing?.tagName==='SELECT'){const o=[...marketing.options].find(o=>/marketing/i.test(o.text));marketing.value=o.value;marketing.dispatchEvent(new Event('change',{bubbles:true}));} }
});
await page.evaluate(() => {
 const text=document.body.innerText;
 const headings=[...document.querySelectorAll('h1,h2,h3,h4,h5')];
 const m=headings.find(e=>/marketing/i.test(e.innerText));
 let values=[];
 if(m){let n=m.nextElementSibling;while(n&&!/^H[1-5]$/.test(n.tagName)){values.push(n.innerText);n=n.nextElementSibling;} }
 if(!values.length) values=text.split('\n').filter((l,i,a)=>/marketing/i.test(l)||(/marketing/i.test(a[i+1]||'')));
 return {url:location.href,title:document.title,h1:document.querySelector('h1')?.innerText,key_text:values[0]||'Careers',values,answer:values.join('\n')};
});
